import './index.css'

const SimilarProductItem = props => {
  const {productDetails} = props
  const {imageUrl} = productDetails

  return (
    <li className="similar-product-item">
      <img
        src={imageUrl}
        alt="similar product"
        className="similar-product-image"
      />
      <p className="">{}</p>
    </li>
  )
}

export default SimilarProductItem
